  method: 'POST',
  url: `${apiUrl}/login`,
  failOnStatusCode: false,
  body: {
    username: "unknown@user.fr",
    password: "wrongpassword"
  }
}).then(response => {
  expect(response.status).to.eq(401);
});

const productID = 9;
cy.request({
  method: 'GET',
  url: `${apiUrl}/products/${productID}`,
  failOnStatusCode: false
}).then(response => {
  expect(response.status).to.eq(200);
  expect(response.body).to.include.all.keys("id", "name", "availableStock", "skin", "aromas", "ingredients", "description", "price", "picture", "varieties");
  expect(response.body.id).to.eq(productID);
});

cy.request({
  method: 'PUT',
  //Utilisation de PUT pour correspondre au fonctionnement actuel de l'API (anomalie relevée par Marie)
  url: `${apiUrl}/orders/add`,
  headers: {
    Authorization: `Bearer ${token}`
  },
  body: {
    product: 5,
    quantity: 1
  }
}).then(response => {
  expect(response.status).to.eq(200);
  expect(response.body).to.have.property("orderLines");
  const productInCart = response.body.orderLines.find(line => line.product.id === 5);
  expect(productInCart).to.exist;
  expect(productInCart.quantity).to.be.at.least(1);
});

