const reviewData = {
  title: _faker.fakerFR.word.words(3),
  comment: _faker.fakerFR.commerce.productDescription(),
  rating: _faker.fakerFR.number.int({
    min: 1,
    max: 5
  })
};
cy.request({
  method: 'POST',
  url: `${apiUrl}/reviews`,
  headers: {
    Authorization: `Bearer ${token}`
  },
  body: reviewData
}).then(response => {
  expect(response.status).to.eq(200);
  expect(response.body.title).to.eq(reviewData.title);
  expect(response.body.comment).to.eq(reviewData.comment);
  expect(response.body.rating).to.eq(reviewData.rating);
});
